<?php

namespace App\Services\Parsers;

use App\Contracts\ParserInterface;
use App\DTO\NormalizedDocument;
use App\DTO\ParsedMessage;
use App\DTO\ParsedTransaction;
use App\DTO\ParserContext;
use App\DTO\ParserResult;
use App\Enums\ConfidenceLevel;
use Carbon\Carbon;

/**
 * Concrete parser for Bank Central Asia (BCA) notifications.
 *
 * Philosophy
 * ──────────
 * This parser extracts structured facts only.
 * It does NOT build any human-readable description or label.
 * All user-facing text is generated by TransactionDescriptionBuilder.
 *
 * The `merchant` field is intentionally kept as the raw extracted merchant name
 * (e.g. "INDOMARET JAYA") — without any prefix like "QRIS" or "Transfer to".
 * TransactionDescriptionBuilder composes the final label using `template` + `merchant`
 * + `counterparty` + `keterangan` (remarks).
 *
 * Supported templates (confirmed production samples)
 * ───────────────────────────────────────────────────
 *   BCA_QRIS            — QRIS payment
 *   BCA_TRANSFER        — Transfer to/from BCA account
 *   BCA_VIRTUAL_ACCOUNT — Transfer to BCA Virtual Account
 *   BCA_CASH_DEPOSIT    — Cardless cash deposit (Setor Tunai)
 *   BCA_CASH_WITHDRAW   — Cardless cash withdrawal (Tarik Tunai)
 */
class BCAParser extends AbstractParser implements ParserInterface
{
    /**
     * Map of Indonesian month names and abbreviations to English equivalents.
     */
    private const MONTH_MAP = [
        'januari'   => 'January',
        'februari'  => 'February',
        'maret'     => 'March',
        'april'     => 'April',
        'mei'       => 'May',
        'juni'      => 'June',
        'juli'      => 'July',
        'agustus'   => 'August',
        'september' => 'September',
        'oktober'   => 'October',
        'november'  => 'November',
        'desember'  => 'December',
        'jan'       => 'Jan',
        'feb'       => 'Feb',
        'mar'       => 'Mar',
        'apr'       => 'Apr',
        'jun'       => 'Jun',
        'jul'       => 'Jul',
        'agu'       => 'Aug',
        'sep'       => 'Sep',
        'okt'       => 'Oct',
        'nov'       => 'Nov',
        'des'       => 'Dec',
    ];

    public function supports(NormalizedDocument $document, ParserContext $context): bool
    {
        // Primary: BCA sender is the strongest signal
        if (preg_match('/(bca|cba)@bca\.co\.id/i', $document->from)) {
            return true;
        }

        // Reject known non-BCA senders — subject keywords must not override bank identity
        if (preg_match('/bankmandiri\.co\.id|@mandiri/i', $document->from)) {
            return false;
        }

        // Fallback: subject contains BCA-style keywords and sender is unknown
        return (bool) preg_match('/(Transfer|QRIS|Debit|Credit|Setor|Tarik)/i', $document->subject);
    }

    public function parse(NormalizedDocument $document, ParserContext $context): ParserResult
    {
        $fields = $document->fields;

        // 1. Parse Date and Time
        $rawDate   = $fields->get('tanggal');
        $rawTime   = $fields->get('jam');
        $parsedDate = $this->interpretDate($rawDate, $rawTime);

        // 2. Parse Amount (Integer Rupiah)
        $rawNominal = $fields->get('nominal');
        $amount = 0;
        if ($rawNominal) {
            $amount = (int) round($this->cleanCurrency($rawNominal));
        }

        // 3. Structured facts — extracted as-is, no label building here
        $reference          = $fields->get('reference');
        $sourceAccount      = $fields->get('source_account');
        $destinationAccount = $fields->get('destination_account');
        $merchant           = $fields->get('merchant');     // Raw merchant name (QRIS / debit)
        $counterparty       = $fields->get('counterparty'); // Human name of sender/recipient
        $company            = $fields->get('company');      // VA company name
        $keterangan         = $fields->get('keterangan');   // Remarks / notes
        $template           = $fields->get('template');     // Template identifier

        // 4. Determine flow and type from template + fallback
        $flow = $this->interpretFlow($document->subject, $document->body, $template);
        $type = $this->interpretType($template, $document->subject, $document->body);

        // 5. Canonical merchant resolution
        // For non-QRIS/debit templates, the merchant field from the email is usually
        // the account number, not a human name. We use counterparty or company instead.
        // TransactionDescriptionBuilder will build the final label, but we need a
        // sensible merchant value for the DTO as well.
        $resolvedMerchant = $this->resolveMerchant(
            template: $template,
            merchant: $merchant,
            counterparty: $counterparty,
            company: $company,
            flow: $flow,
            sourceAccount: $sourceAccount,
            destinationAccount: $destinationAccount,
        );

        $bank = 'BCA';

        // 6. Confidence scoring
        $validCount = 0;
        if (!empty($resolvedMerchant) && !str_contains(strtolower($resolvedMerchant), 'unknown')) $validCount++;
        if ($amount > 0)                $validCount++;
        if (!empty($reference))         $validCount++;
        if ($parsedDate !== null)       $validCount++;
        if (!empty($flow))              $validCount++;
        if (!empty($bank))              $validCount++; // Always present

        $confidence = match (true) {
            $validCount === 6 => ConfidenceLevel::HIGH,
            $validCount === 5 => ConfidenceLevel::MEDIUM,
            default           => ConfidenceLevel::LOW,
        };

        // 7. Build DTOs
        $parsedMessage = new ParsedMessage(
            provider:   'BCA',
            intent:     'TRANSACTION',
            confidence: $confidence,
            rawFields:  $fields->all()
        );

        $parsedTransaction = null;
        if ($amount > 0 && $parsedDate !== null) {
            $parsedTransaction = new ParsedTransaction(
                merchant:           $resolvedMerchant,
                amount:             $amount,
                transactionDate:    $parsedDate,
                reference:          $reference,
                bank:               $bank,
                flow:               $flow,
                type:               $type,
                sourceAccount:      $sourceAccount,
                destinationAccount: $destinationAccount,
                rawAmount:          $rawNominal ?? '',
                status:             'SUCCESS',
                confidence:         $confidence,
                notes:              $keterangan,
                template:           $template,
                counterparty:       $counterparty,
                metadata:           [
                    'keterangan' => $keterangan,
                ],
            );
        }

        return new ParserResult(
            supported:         true,
            warnings:          [],
            errors:            [],
            confidence:        $confidence,
            parsedMessage:     $parsedMessage,
            parsedTransaction: $parsedTransaction
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Private helpers
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Resolve the canonical merchant value for the DTO.
     *
     * Rules:
     *  - For QRIS: use the raw extracted merchant name (it's already the QRIS merchant)
     *  - For Virtual Account: use the company name (VA product/issuer)
     *  - For Transfer: use counterparty (human name) if available
     *  - For Cash: return null (no merchant — TransactionDescriptionBuilder handles label)
     *  - Fallback: account number or 'Unknown Merchant'
     */
    private function resolveMerchant(
        ?string $template,
        ?string $merchant,
        ?string $counterparty,
        ?string $company,
        string  $flow,
        ?string $sourceAccount,
        ?string $destinationAccount
    ): ?string {
        return match ($template) {
            'BCA_QRIS'            => $merchant ?: 'Unknown Merchant',
            'BCA_VIRTUAL_ACCOUNT' => $company ?: $merchant ?: 'Unknown Merchant',
            'BCA_CASH_DEPOSIT',
            'BCA_CASH_WITHDRAW'   => null, // Label built by TransactionDescriptionBuilder
            'BCA_TRANSFER',
            null                  => $counterparty
                                  ?: $merchant
                                  ?: ($flow === 'OUT' ? $destinationAccount : $sourceAccount)
                                  ?: 'Unknown Merchant',
            default               => $counterparty ?: $merchant ?: 'Unknown Merchant',
        };
    }

    /**
     * Interpret raw date and time strings into a Carbon instance.
     */
    private function interpretDate(?string $rawDate, ?string $rawTime): ?Carbon
    {
        if (empty($rawDate)) {
            return null;
        }

        $cleanDate = strtolower(trim($rawDate));

        foreach (self::MONTH_MAP as $id => $en) {
            $cleanDate = str_replace($id, $en, $cleanDate);
        }

        $timeStr = $rawTime ? trim($rawTime) : '00:00:00';
        if (preg_match('/^\d{2}:\d{2}$/', $timeStr)) {
            $timeStr .= ':00';
        }

        $formats = ['d/m/Y', 'd M Y', 'd-M-Y', 'j M Y', 'd F Y', 'j F Y'];

        foreach ($formats as $fmt) {
            $parsed = $this->parseDate($cleanDate . ' ' . $timeStr, $fmt . ' H:i:s');
            if ($parsed) return $parsed;

            $parsed = $this->parseDate($cleanDate, $fmt);
            if ($parsed) return $parsed;
        }

        return null;
    }

    /**
     * Determine transaction flow direction (IN / OUT).
     */
    private function interpretFlow(string $subject, string $body, ?string $template): string
    {
        // Cash deposit is always IN
        if ($template === 'BCA_CASH_DEPOSIT') return 'IN';
        // Cash withdrawal is always OUT
        if ($template === 'BCA_CASH_WITHDRAW') return 'OUT';

        $sl = strtolower($subject);
        $bl = strtolower($body);

        if (
            str_contains($sl, 'masuk') ||
            str_contains($sl, 'diterima') ||
            str_contains($sl, 'credit') ||
            str_contains($bl, 'transfer masuk') ||
            str_contains($bl, 'telah diterima') ||
            str_contains($bl, 'dana masuk')
        ) {
            return 'IN';
        }

        return 'OUT';
    }

    /**
     * Determine transaction type string.
     */
    private function interpretType(?string $template, string $subject, string $body): string
    {
        if ($template !== null) {
            return match ($template) {
                'BCA_QRIS'            => 'QRIS',
                'BCA_VIRTUAL_ACCOUNT' => 'TRANSFER',
                'BCA_CASH_DEPOSIT'    => 'CASH_DEPOSIT',
                'BCA_CASH_WITHDRAW'   => 'CASH_WITHDRAW',
                'BCA_TRANSFER'        => 'TRANSFER',
                default               => 'TRANSFER',
            };
        }

        // Template-less fallback
        $sl = strtolower($subject);
        $bl = strtolower($body);

        if (str_contains($sl, 'qris') || str_contains($bl, 'qris')) return 'QRIS';
        if (str_contains($sl, 'credit') || str_contains($bl, 'kartu kredit')) return 'CREDIT_CARD';
        if (str_contains($sl, 'debit') || str_contains($bl, 'kartu debit') || str_contains($bl, 'debet')) return 'DEBIT_CARD';

        return 'TRANSFER';
    }
}
